import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Was tun, wenn das Dashboard läuft, aber sich falsch verhält?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/04.fehlerbehebung/02.dashboard-bedienung.md"},"headers":[],"relativePath":"de/adapter/esphome/fehlerbehebung/dashboard-bedienung.md","filePath":"de/adapter/esphome/fehlerbehebung/dashboard-bedienung.md","lastUpdated":null}'),d={name:"de/adapter/esphome/fehlerbehebung/dashboard-bedienung.md"};function s(n,e,o,h,l,b){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="was-tun-wenn-das-dashboard-lauft-aber-sich-falsch-verhalt" tabindex="-1">Was tun, wenn das Dashboard läuft, aber sich falsch verhält? <a class="header-anchor" href="#was-tun-wenn-das-dashboard-lauft-aber-sich-falsch-verhalt" aria-label="Permalink to &quot;Was tun, wenn das Dashboard läuft, aber sich falsch verhält?&quot;">​</a></h1><p><a id="ota-update-abort-time-out"></a></p><h2 id="warum-bricht-das-ota-update-ab-oder-lauft-in-ein-timeout" tabindex="-1">Warum bricht das OTA-Update ab oder läuft in ein Timeout? <a class="header-anchor" href="#warum-bricht-das-ota-update-ab-oder-lauft-in-ein-timeout" aria-label="Permalink to &quot;Warum bricht das OTA-Update ab oder läuft in ein Timeout?&quot;">​</a></h2><p>Das OTA-Update läuft zwischen Dashboard und Gerät, der Adapter ist daran nicht beteiligt.</p><p>Ein Timeout direkt nach einem vollständigen Upload ist normal. Das Gerät startet mit der neuen Firmware neu und ist kurz nicht erreichbar, danach verbindet sich der Adapter wieder.</p><p>Bricht der Upload mittendrin ab, liegt es fast immer am Netz oder am Gerät:</p><ol><li>Prüf das WLAN-Signal des Geräts. Unter etwa -80 dBm brechen Uploads oft ab.</li><li>Prüf, ob eine Firewall zwischen ioBroker-Rechner und Gerät den OTA-Port sperrt.</li><li>Hilft das nicht, flashe einmal per Kabel.</li></ol><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/dashboard-einschalten#flash-device-first-time-if">Per Kabel flashen</a></p><p><a id="dashboard-ui-broken-browser"></a></p><h2 id="warum-ist-die-dashboard-oberflache-im-browser-fehlerhaft" tabindex="-1">Warum ist die Dashboard-Oberfläche im Browser fehlerhaft? <a class="header-anchor" href="#warum-ist-die-dashboard-oberflache-im-browser-fehlerhaft" aria-label="Permalink to &quot;Warum ist die Dashboard-Oberfläche im Browser fehlerhaft?&quot;">​</a></h2><p>Der Tab „ESPHome“ zeigt das Dashboard nur eingebettet, die Oberfläche selbst kommt von ESPHome. Darstellungsfehler im Editor oder im Log-Fenster liegen deshalb meist am Dashboard oder am Browser.</p><ol><li>Öffne das Dashboard direkt in einem eigenen Browser-Tab unter <code>http://&lt;ioBroker-IP&gt;:6052</code>.</li><li>Leere den Cache des Browsers oder lade die Seite mit Strg+F5 neu.</li><li>Probier einen anderen Browser.</li></ol><p>Ist der Fehler auch direkt im Browser da, liegt er im Dashboard. Eine andere ESPHome-Version kann dann helfen.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Dashboard-Version wählen</a></p>',14)])])}const c=a(d,[["render",s]]);export{m as __pageData,c as default};
